seven_grid_cellrow_ctor   0x100199fc2  (void *cell5@rdi)  # FGRC the cell row ctor's tail call for cell 5: cells 6 and 7
seven_grid_wirerow_ctor   0x10019a024  (void *row@rbx)  # FGRW the wire row ctor after record 5: records 6 and 7
