seven_grid_wirerow_mark   0x10019a159  (void *row@rdi, uint32_t event@rsi)  # the wire row's event 13 (state reset 0x10019d460), its only exit: records 6 and 7
seven_grid_wirerow_flush  0x10019a1f5  (void *rec5@rdi)  # FGR58E74A the wire row flush (FretGrid flush 0x10019cf30) before its tail call for record 5: 6 and 7
seven_grid_wires_dtor     0x10019faa1  (void *grid@r15, int64_t at@r14)  # FGR592959 the FretGrid dtor's wire-row loop, after records 7..2 of a row: records 1 and 0

